    if (!Array.isArray(value) || value.some((entry) => typeof entry !== 'string' || entry.trim() === '')) {
        throw new Error(`[ModuleManifest] ${label} must be an array of non-empty strings`);
    }

    return value.map((entry) => entry.trim());
