/**
 * build.js — click-build reveal element factory.
 *
 * A `.build` wrapper toggles `data-visible` based on the current click count
 * relative to its `at` step. The CSS handles the opacity/transform/filter
 * transition (see slides.css §build).
 *
 * On mount, each Build element calls `service.registerMax(at, slideIndex)` so
 * the service knows the slide's build ceiling. On BUILD_ADVANCED events, the
 * element updates its `data-visible` attribute based on `clicks >= at`.
 *
 * Pure DOM construction. textContent for all user strings.
 */

/**
 * Create a build-reveal wrapper.
 *
 * @param {object} opts
 * @param {number} opts.at — 1-indexed build step at which this element becomes visible
 * @param {HTMLElement[]} [opts.children] — DOM nodes to wrap
 * @param {object} [opts.service] — SlideDeckService (for registerMax)
 * @param {number} [opts.slideIndex] — slide index this build lives on
 * @param {number} [opts.currentClicks] — initial clicks (for first render)
 * @returns {HTMLElement} `.build` wrapper with `data-visible` set
 */
export function createBuildElement({ at, children = [], service = null, slideIndex, currentClicks = 0 } = {}) {
    const step = Math.max(1, Number(at) || 1);
    const wrap = document.createElement('div');
    wrap.className = 'build';
    wrap.dataset.buildStep = String(step);
    wrap.dataset.visible = currentClicks >= step ? 'true' : 'false';

    for (const child of children) {
        if (child instanceof Node) wrap.appendChild(child);
    }

    if (service && typeof service.registerMax === 'function') {
        service.registerMax(step, slideIndex);
    }

    return wrap;
}

/**
 * Subscribe a build element to BUILD_ADVANCED events for its slide.
 * Returns an unsubscribe function.
 */
export function bindBuildToService(buildEl, eventBus, slideIndex) {
    if (!eventBus?.subscribe) return () => {};
    const step = Number(buildEl.dataset.buildStep) || 1;
    const handler = (payload) => {
        if (Number.isFinite(slideIndex) && payload?.slide !== slideIndex) return;
        buildEl.dataset.visible = (payload?.click || 0) >= step ? 'true' : 'false';
    };
    return eventBus.subscribe('BUILD_ADVANCED', handler);
}

/**
 * Re-render a build element's visibility state from raw clicks.
 * Used by deck.js when first rendering a slide that already has clicks > 0
 * (e.g. navigating back).
 */
export function syncBuildVisibility(buildEl, clicks) {
    const step = Number(buildEl.dataset.buildStep) || 1;
    buildEl.dataset.visible = (clicks || 0) >= step ? 'true' : 'false';
}

/**
 * transitions.js — CSS-first slide enter/exit orchestrator.
 *
 * animateSlideTransition swaps the slide-stage's content while toggling
 * data-transition on the stage. CSS keyframes (see slides.css §transitions)
 * drive the visual animation. We only manage the timing/sequencing.
 *
 * Respects prefers-reduced-motion — the CSS disables motion; we still swap
 * content synchronously so the function resolves immediately.
 */

const TRANSITION_DURATION_MS = 420; // matches --motion-duration-slow token

/**
 * Animate a slide transition.
 *
 * @param {HTMLElement} stage — the `.slide-stage` element
 * @param {'next'|'prev'} direction — which way the new slide is coming from
 * @param {() => void} swapFn — function that swaps the slide DOM content
 * @returns {Promise<void>} resolves when enter animation completes
 */
export function animateSlideTransition(stage, direction, swapFn) {
    if (!stage || typeof swapFn !== 'function') return Promise.resolve();

    const doc = stage.ownerDocument || (typeof document !== 'undefined' ? document : null);
    const reducedMotion = doc && winMatch(doc) ? true : false;

    if (reducedMotion) {
        swapFn();
        return Promise.resolve();
    }

    return new Promise((resolve) => {
        const dir = direction === 'prev' ? 'right' : 'left';
        stage.dataset.transition = 'exit ' + dir;

        const exitDone = () => {
            swapFn();
            stage.dataset.transition = 'enter ' + dir;

            // Wait for enter animation to finish, then clean up.
            const enterDone = () => {
                stage.removeEventListener('animationend', enterDone);
                delete stage.dataset.transition;
                resolve();
            };
            stage.addEventListener('animationend', enterDone);
            // Safety timeout in case animationend doesn't fire (hidden tab etc.)
            setTimeout(() => {
                stage.removeEventListener('animationend', enterDone);
                delete stage.dataset.transition;
                resolve();
            }, TRANSITION_DURATION_MS + 80);
        };

        // For exit, we wait a short tick then swap. animationend on exit isn't
        // reliable across browsers when the same property transitions twice.
        setTimeout(exitDone, 60);
    });
}

function winMatch(doc) {
    const win = doc.defaultView || (typeof window !== 'undefined' ? window : null);
    if (!win || !win.matchMedia) return false;
    try {
        return win.matchMedia('(prefers-reduced-motion: reduce)').matches;
    } catch {
        return false;
    }
}

/**
 * thumbnails.js — canvas-based slide preview for rail and grid chrome.
 *
 * Renders a slide element to an offscreen canvas at a fractional scale. Used by
 * the rail (sidebar) and grid (overview) chrome to give the audience a glance
 * of every slide without rendering each at full size.
 *
 * Implementation note: full foreignObject-SVG-to-canvas rasterization is
 * browser-flaky (taint, CORS on fonts). We use a layout-driven approach that
 * reads the slide element's bounding rect and copies its outerHTML into an
 * iframe-rendered SVG, then draws that SVG to canvas. For environments
 * without canvas (jsdom), we return a placeholder canvas with a label so
 * tests can still verify the rail/grid mount correctly.
 *
 * This is best-effort: if rasterization fails, callers fall back to a labeled
 * placeholder.
 */

const PLACEHOLDER_BG = 'var(--surface-muted)';
const PLACEHOLDER_FG = 'var(--foreground-muted)';

/**
 * Render a slide element to a canvas thumbnail.
 *
 * @param {HTMLElement} slideEl
 * @param {number} [scale=0.15] — fraction of full size (0.15 = ~15%)
 * @param {object} [opts]
 * @param {number} [opts.baseWidth=1280] — assumed slide width when slideEl has no layout
 * @param {number} [opts.baseHeight=720]
 * @returns {Promise<HTMLCanvasElement>}
 */
export async function renderThumbnail(slideEl, scale = 0.15, opts = {}) {
    const baseWidth = opts.baseWidth || 1280;
    const baseHeight = opts.baseHeight || 720;
    const w = Math.max(40, Math.round(baseWidth * scale));
    const h = Math.max(30, Math.round(baseHeight * scale));

    const doc = slideEl?.ownerDocument || (typeof document !== 'undefined' ? document : null);
    const canvas = doc ? doc.createElement('canvas') : null;
    if (!canvas) return null;
    canvas.width = w;
    canvas.height = h;
    canvas.className = 'slide-thumb';

    const ctx = canvas.getContext && canvas.getContext('2d');
    if (!ctx) return canvas;

    // Placeholder fill — works in jsdom and as a fallback in browsers
    try {
        ctx.fillStyle = '#f3f3f3';
        ctx.fillRect(0, 0, w, h);
        ctx.fillStyle = '#888';
        ctx.font = Math.max(8, Math.round(h * 0.10)) + 'px sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        const label = String(slideEl?.dataset?.slideType || slideEl?.dataset?.layout || 'slide');
        ctx.fillText(label, w / 2, h / 2);
    } catch {
        // jsdom canvas: fillText may throw — leave the placeholder blank
    }

    // Best-effort browser rasterization using the SVG <foreignObject> trick.
    // Skipped in jsdom (no DOMParser XML serialization of computed styles).
    const win = doc.defaultView || (typeof window !== 'undefined' ? window : null);
    if (!win || !slideEl || typeof win.btoa !== 'function') return canvas;
    if (typeof slideEl.outerHTML !== 'string') return canvas;

    try {
        const rect = slideEl.getBoundingClientRect();
        const rw = rect.width || baseWidth;
        const rh = rect.height || baseHeight;
        const xml = new win.XMLSerializer().serializeToString(slideEl);
        const svgString =
            '<svg xmlns="http://www.w3.org/2000/svg" width="' + rw + '" height="' + rh + '">' +
            '<foreignObject width="100%" height="100%">' +
            xml +
            '</foreignObject></svg>';
        const dataUrl = 'data:image/svg+xml;base64,' + win.btoa(unescape(encodeURIComponent(svgString)));
        const img = new win.Image();
        await new Promise((resolve, reject) => {
            img.onload = resolve;
            img.onerror = reject;
            img.src = dataUrl;
            setTimeout(reject, 250); // bail on slow decode
        });
        ctx.drawImage(img, 0, 0, w, h);
    } catch {
        // foreignObject taint / serialization failure → keep placeholder
    }

    return canvas;
}

/**
 * Build a non-canvas placeholder (used when canvas rasterization is unavailable).
 */
export function createPlaceholderThumbnail(label, scale = 0.15, opts = {}) {
    const baseWidth = opts.baseWidth || 1280;
    const baseHeight = opts.baseHeight || 720;
    const doc = typeof document !== 'undefined' ? document : null;
    if (!doc) return null;
    const el = doc.createElement('div');
    el.className = 'slide-thumb slide-thumb--placeholder';
    el.textContent = String(label || 'slide');
    el.style.width = Math.max(40, Math.round(baseWidth * scale)) + 'px';
    el.style.aspectRatio = String(baseWidth + ' / ' + baseHeight);
    // Note: inline styles here are intentional for the placeholder fallback only.
    // Real slide thumbnails use canvas. Background uses tokens.
    el.style.background = PLACEHOLDER_BG;
    el.style.color = PLACEHOLDER_FG;
    return el;
}

/**
 * annotator.js — SVG freehand drawing overlay.
 *
 * Mounted inside the slide-stage when `drawing=true` (UI_STATE_CHANGED).
 * Listens to pointer events on the SVG, publishes INTENT_ANNOTATION_STROKE
 * intents with point arrays. Reads ANNOTATION_UPDATED to render persisted
 * strokes.
 *
 * Type II: subscribes to events, publishes intents. No direct service mutation.
 * Pure SVG construction — no inline styles for stroke colors (uses data-color
 * attribute + CSS rule). Returns a cleanup function.
 */

const DEFAULT_COLOR = 'currentColor';
const DEFAULT_WIDTH = 3;

/**
 * Mount the annotator overlay on a container.
 *
 * @param {HTMLElement} container — the slide-stage element
 * @param {object} eventBus
 * @param {object} service — SlideDeckService (for current slide index)
 * @returns {() => void} cleanup function
 */
export function initAnnotator(container, eventBus, service) {
    if (!container || !eventBus) return () => {};
    const doc = container.ownerDocument || (typeof document !== 'undefined' ? document : null);
    if (!doc) return () => {};

    const svg = doc.createElementNS('http://www.w3.org/2000/svg', 'svg');
    svg.setAttribute('class', 'slide-annotator');
    svg.setAttribute('data-active', 'false');
    svg.setAttribute('aria-hidden', 'true');
    container.appendChild(svg);

    let currentStroke = null;
    let currentPath = null;
    const subs = [];

    // Render persisted strokes when ANNOTATION_UPDATED fires.
    const renderAll = (strokes) => {
        while (svg.firstChild) svg.removeChild(svg.firstChild);
        for (const stroke of (strokes || [])) {
            svg.appendChild(buildPath(stroke));
        }
    };

    subs.push(eventBus.subscribe('ANNOTATION_UPDATED', (payload) => {
        const idx = service?.index;
        if (Number.isFinite(idx) && payload?.slide !== idx) return;
        renderAll(payload?.strokes);
    }));

    // Reflect drawing state from UI_STATE_CHANGED.
    subs.push(eventBus.subscribe('UI_STATE_CHANGED', (payload) => {
        svg.dataset.active = payload?.drawing ? 'true' : 'false';
    }));

    // Pointer capture → live stroke preview → commit on pointerup.
    const onPointerDown = (e) => {
        if (svg.dataset.active !== 'true') return;
        e.preventDefault();
        const pt = toLocalPoint(svg, e);
        currentStroke = {
            points: [pt],
            color: DEFAULT_COLOR,
            width: DEFAULT_WIDTH
        };
        currentPath = buildPath(currentStroke);
        svg.appendChild(currentPath);
        try { svg.setPointerCapture(e.pointerId); } catch { /* noop */ }
    };

    const onPointerMove = (e) => {
        if (!currentStroke || !currentPath) return;
        e.preventDefault();
        const pt = toLocalPoint(svg, e);
        currentStroke.points.push(pt);
        currentPath.setAttribute('d', toPathData(currentStroke.points));
    };

    const onPointerUp = (e) => {
        if (!currentStroke) return;
        e.preventDefault();
        const committed = currentStroke;
        currentStroke = null;
        currentPath = null;
        try { svg.releasePointerCapture(e.pointerId); } catch { /* noop */ }
        if (committed.points.length > 1 && service && Number.isFinite(service.index)) {
            eventBus.publish('INTENT_ANNOTATION_STROKE', {
                slide: service.index,
                points: committed.points,
                color: committed.color,
                width: committed.width
            });
        }
    };

    svg.addEventListener('pointerdown', onPointerDown);
    svg.addEventListener('pointermove', onPointerMove);
    svg.addEventListener('pointerup', onPointerUp);
    svg.addEventListener('pointercancel', onPointerUp);

    // Initial render of current slide's persisted strokes.
    if (service && typeof service.getAnnotations === 'function') {
        renderAll(service.getAnnotations(service.index));
    }

    return () => {
        subs.forEach((unsub) => unsub && unsub());
        svg.removeEventListener('pointerdown', onPointerDown);
        svg.removeEventListener('pointermove', onPointerMove);
        svg.removeEventListener('pointerup', onPointerUp);
        svg.removeEventListener('pointercancel', onPointerUp);
        if (svg.parentNode) svg.parentNode.removeChild(svg);
    };
}

function buildPath(stroke) {
    const doc = typeof document !== 'undefined' ? document : null;
    if (!doc) return null;
    const path = doc.createElementNS('http://www.w3.org/2000/svg', 'path');
    path.setAttribute('class', 'slide-annotation');
    path.setAttribute('data-color', stroke.color || DEFAULT_COLOR);
    path.setAttribute('stroke-width', String(stroke.width || DEFAULT_WIDTH));
    path.setAttribute('fill', 'none');
    path.setAttribute('stroke-linecap', 'round');
    path.setAttribute('stroke-linejoin', 'round');
    path.setAttribute('d', toPathData(stroke.points || []));
    return path;
}

function toPathData(points) {
    if (!Array.isArray(points) || points.length === 0) return '';
    if (points.length === 1) {
        return 'M' + points[0].x + ',' + points[0].y + ' l0.1,0.1';
    }
    let d = 'M' + points[0].x + ',' + points[0].y;
    for (let i = 1; i < points.length; i++) {
        d += ' L' + points[i].x + ',' + points[i].y;
    }
    return d;
}

function toLocalPoint(svg, e) {
    const rect = svg.getBoundingClientRect();
    return {
        x: e.clientX - rect.left,
        y: e.clientY - rect.top
    };
}

