import { el, createSlideShell, createKicker, createTitleWithAccent, createFoot, container } from './_shared.js';

/**
 * cover — opening slide. Always the first slide. Full-viewport with optional
 * background image under a scrim. Center-aligned by default.
 *
 * Config: `{ kicker, title, subtitle, foot?, image?, center=true }`
 */
export function createCoverSlide(config = {}) {
    const slide = createSlideShell('cover', { center: true });
    if (config.image) {
        const bg = el('div', { className: 'cover-bg' });
        bg.dataset.image = 'present';
        // Actual image rendered via CSS background-image (set by data-attr →
        // CSS rule, never as inline style). Caller may set CSS in slides.css.
        slide.appendChild(bg);
    }
    const inner = el('div', { className: 'cover-inner', children: [
        createKicker(config.kicker),
        createTitleWithAccent(config.title, { level: 'h1', className: 'display' }),
        config.subtitle ? el('p', { className: 'subhead', text: String(config.subtitle) }) : null,
        createFoot(config.foot)
    ].filter(Boolean) });
    slide.appendChild(inner);
    return slide;
}

import { el, createSlideShell, createKicker, createHeading, createBody, container } from './_shared.js';
import { createCodeWindowSlide } from './code-window.js';
import { createBrowserFrameSlide } from './browser-frame.js';

/**
 * split — text + side media panel. Two-column. `flip: true` swaps sides.
 *
 * Config: `{ kicker?, title, body?, media, flip?, center=false }`
 * `media` is an embedded config: `{ type, ... }` where type can be
 * 'image', 'code-window', 'browser-frame', 'panel', 'globe', 'chart'.
 */
export function createSplitSlide(config = {}) {
    const slide = createSlideShell('split', { center: false });
    if (config.flip) slide.dataset.flip = 'true';

    const text = el('div', { className: 'split-text', children: [
        createKicker(config.kicker),
        createHeading(config.title),
        createBody(config.body)
    ].filter(Boolean) });

    const media = el('div', { className: 'split-media' });
    const mediaEl = renderMedia(config.media);
    if (mediaEl) media.appendChild(mediaEl);

    const inner = config.flip
        ? container([media, text])
        : container([text, media]);
    slide.appendChild(inner);
    return slide;
}

/**
 * Render an embedded media panel based on its `type` field.
 * Exported for reuse by other layouts (spotlight, bento tile media).
 */
export function renderMedia(mediaConfig) {
    if (!mediaConfig || typeof mediaConfig !== 'object') return null;
    switch (mediaConfig.type) {
        case 'image':
            return el('div', { className: 'media-image', dataset: { src: mediaConfig.src || '' } });
        case 'code-window':
            return createCodeWindowSlide(mediaConfig);
        case 'browser-frame':
            return createBrowserFrameSlide(mediaConfig);
        case 'panel':
            return el('div', { className: 'media-panel', dataset: { color: mediaConfig.color || 'primary' } });
        case 'globe':
            return el('div', { className: 'media-globe', dataset: { layout: 'globe' } });
        case 'chart':
            return el('div', { className: 'media-chart', dataset: { chartType: mediaConfig.chartType || 'bar' } });
        default:
            return null;
    }
}

import { el, createSlideShell, createKicker, createHeading, container, formatFigure } from './_shared.js';

/**
 * bento — asymmetric tile grid. 3–5 proof points with figures, titles, short
 * bodies. Each tile can span columns (`c`) and rows (`r`) and use a variant
 * (`glow` | `accent`).
 *
 * Config: `{ kicker?, title?, tiles: [{ k, fig?, title?, body?, c?, r?, variant?, img? }] }`
 */
export function createBentoSlide(config = {}) {
    const slide = createSlideShell('bento', { center: false });
    const tiles = Array.isArray(config.tiles) ? config.tiles : [];

    const header = el('div', { className: 'bento-header', children: [
        createKicker(config.kicker),
        createHeading(config.title)
    ].filter(Boolean) });

    const grid = el('div', { className: 'bento-grid' });
    for (const tile of tiles) {
        grid.appendChild(buildTile(tile));
    }

    slide.appendChild(container([header, grid]));
    return slide;
}

function buildTile(tile = {}) {
    const t = el('div', { className: 'bento-tile' });
    if (tile.c) t.dataset.colSpan = String(tile.c);
    if (tile.r) t.dataset.rowSpan = String(tile.r);
    if (tile.variant) t.dataset.variant = String(tile.variant);
    if (tile.img) t.dataset.image = String(tile.img);

    const children = [];
    if (tile.k) children.push(el('p', { className: 'kicker', text: String(tile.k) }));
    if (tile.fig) children.push(el('p', { className: 'figure', text: formatFigure(tile.fig) }));
    if (tile.title) children.push(el('p', { className: 'tile-title', text: String(tile.title) }));
    if (tile.body) children.push(el('p', { className: 'tile-body', text: String(tile.body) }));

    for (const child of children.filter(Boolean)) t.appendChild(child);
    return t;
}

import { el, createSlideShell, createKicker, createHeading, container, formatFigure } from './_shared.js';
import { mountCountUp } from '../ui/count-up.js';

/**
 * stat-grid — 2–4 headline metrics with labels + captions. Each value animates
 * from 0 on slide-enter via CountUp.
 *
 * Config: `{ kicker?, title?, stats: [{ value: figureSpec, label, caption? }] }`
 */
export function createStatGridSlide(config = {}) {
    const slide = createSlideShell('stat-grid', { center: true });
    const stats = Array.isArray(config.stats) ? config.stats : [];

    const header = el('div', { className: 'stat-header', children: [
        createKicker(config.kicker),
        createHeading(config.title)
    ].filter(Boolean) });

    const grid = el('div', { className: 'stat-grid' });
    for (const stat of stats) {
        grid.appendChild(buildStat(stat));
    }

    slide.appendChild(container([header, grid]));
    return slide;
}

function buildStat(stat = {}) {
    const card = el('div', { className: 'stat-card' });
    const valueEl = el('p', { className: 'stat-value' });
    valueEl.dataset.figure = JSON.stringify(stat.value || {});
    // Mount count-up once the element is attached to the document — the deck's
    // mountSlide() walks the slide for [data-figure] elements and calls
    // mountCountUp on each. This avoids needing IntersectionObserver setup
    // during pure construction.
    card.appendChild(valueEl);
    if (stat.label) card.appendChild(el('p', { className: 'stat-label', text: String(stat.label) }));
    if (stat.caption) card.appendChild(el('p', { className: 'stat-caption', text: String(stat.caption) }));
    return card;
}

/**
 * Wire up CountUp animations on all `[data-figure]` elements within a slide.
 * Called by deck.js after the slide is attached.
 */
export function wireStatGridCountUps(slideEl, opts = {}) {
    if (!slideEl) return () => {};
    const cleanups = [];
    const targets = slideEl.querySelectorAll('[data-figure]');
    for (const target of targets) {
        let figure = {};
        try { figure = JSON.parse(target.dataset.figure || '{}'); } catch { /* noop */ }
        cleanups.push(mountCountUp(target, figure, opts));
    }
    return () => cleanups.forEach((fn) => fn && fn());
}

import { el, createSlideShell, createKicker, createFoot, container } from './_shared.js';
import { mountCountUp } from '../ui/count-up.js';

/**
 * big-number — one enormous accent figure + caption. Always cited in `foot`.
 * At most one per deck — two giant numbers cancel each other (per §12.5).
 *
 * Config: `{ kicker?, value: figureSpec, caption, foot?, center=true }`
 */
export function createBigNumberSlide(config = {}) {
    const slide = createSlideShell('big-number', { center: true });

    const valueEl = el('p', { className: 'big-number-value' });
    valueEl.dataset.figure = JSON.stringify(config.value || {});

    const inner = el('div', { className: 'big-number-inner', children: [
        createKicker(config.kicker),
        valueEl,
        config.caption ? el('p', { className: 'lead', text: String(config.caption) }) : null,
        createFoot(config.foot)
    ].filter(Boolean) });

    slide.appendChild(inner);
    return slide;
}

export function wireBigNumberCountUp(slideEl, opts = {}) {
    const target = slideEl?.querySelector('[data-figure]');
    if (!target) return () => {};
    let figure = {};
    try { figure = JSON.parse(target.dataset.figure || '{}'); } catch { /* noop */ }
    return mountCountUp(target, figure, opts);
}

import { el, createSlideShell, createFoot, container } from './_shared.js';

/**
 * quote — pull-quote with attribution. Optional background image under scrim.
 *
 * Config: `{ text, name, role?, image?, center=true }`
 */
export function createQuoteSlide(config = {}) {
    const slide = createSlideShell('quote', { center: true });

    const text = el('blockquote', { className: 'quote-text' });
    // Build the quote mark + text as two spans (textContent only)
    const mark = el('span', { className: 'quote-mark', text: '"' });
    text.appendChild(mark);
    if (config.text) {
        text.appendChild(el('span', { className: 'quote-body', text: String(config.text) }));
    }

    const attrib = el('div', { className: 'quote-attribution', children: [
        config.name ? el('p', { className: 'quote-name', text: String(config.name) }) : null,
        config.role ? el('p', { className: 'quote-role', text: String(config.role) }) : null
    ].filter(Boolean) });

    slide.appendChild(container([text, attrib]));
    return slide;
}

import { el, createSlideShell, container } from './_shared.js';

/**
 * cta — closing slide. Always the last slide. Title + subtitle (contact).
 *
 * Config: `{ title, subtitle?, notes?, center=true }`
 */
export function createCtaSlide(config = {}) {
    const slide = createSlideShell('cta', { center: true });
    const inner = el('div', { className: 'cta-inner', children: [
        config.title ? el('h1', { className: 'display', text: String(config.title) }) : null,
        config.subtitle ? el('p', { className: 'subhead', text: String(config.subtitle) }) : null
    ].filter(Boolean) });
    slide.appendChild(inner);
    return slide;
}

