import { el } from './_shared.js';

/**
 * code-window — code block with macOS chrome + optional line highlights.
 * Embedded in `split` media or used standalone (rare).
 *
 * Config: `{ title?, highlight: number[]?, code: string }`
 *
 * Security: code is rendered as textContent of a single <pre><code> block —
 * no syntax highlighter that touches innerHTML, no eval. Lines highlighted by
 * row index via data-line attributes (CSS handles the striping).
 */
export function createCodeWindowSlide(config = {}) {
    const wrap = el('div', { className: 'code-window' });

    const chrome = el('div', { className: 'code-chrome', children: [
        el('span', { className: 'code-dot code-dot--red' }),
        el('span', { className: 'code-dot code-dot--yellow' }),
        el('span', { className: 'code-dot code-dot--green' }),
        config.title ? el('span', { className: 'code-title', text: String(config.title) }) : null
    ].filter(Boolean) });
    wrap.appendChild(chrome);

    const pre = el('pre', { className: 'code-body' });
    const code = el('code');
    code.textContent = typeof config.code === 'string' ? config.code : '';
    pre.appendChild(code);
    wrap.appendChild(pre);

    // Highlight rows via data-line on each line wrapper. We split the source
    // into lines so the CSS can stripe/highlight without innerHTML.
    if (typeof config.code === 'string') {
        pre.removeChild(code);
        const lines = config.code.split('\n');
        const highlight = Array.isArray(config.highlight) ? new Set(config.highlight) : new Set();
        for (let i = 0; i < lines.length; i++) {
            const lineNo = i + 1;
            const line = el('span', {
                className: 'code-line',
                text: lines[i] || ' '
            });
            line.dataset.line = String(lineNo);
            if (highlight.has(lineNo)) line.dataset.highlight = 'true';
            pre.appendChild(line);
            pre.appendChild(el('br'));
        }
    }

    return wrap;
}

import { el } from './_shared.js';

/**
 * browser-frame — app/product screenshot in browser chrome wrapper.
 * Embedded in `split` media or used standalone.
 *
 * Config: `{ url?, screenshot? }` — `screenshot` is a path set via data-attr
 * (CSS handles background-image). No inline styles, no <img src> with
 * user-provided path (defense in depth).
 */
export function createBrowserFrameSlide(config = {}) {
    const frame = el('div', { className: 'browser-frame' });

    const bar = el('div', { className: 'browser-bar', children: [
        el('span', { className: 'browser-dot browser-dot--red' }),
        el('span', { className: 'browser-dot browser-dot--yellow' }),
        el('span', { className: 'browser-dot browser-dot--green' }),
        el('span', { className: 'browser-url', text: String(config.url || '') })
    ] });
    frame.appendChild(bar);

    const body = el('div', { className: 'browser-body' });
    if (config.screenshot) body.dataset.screenshot = String(config.screenshot);
    frame.appendChild(body);

    return frame;
}

import { el, createSlideShell, createKicker, createHeading, container } from './_shared.js';

/**
 * contrast — before/after comparison panels. Each side has a label, title,
 * and bullet points.
 *
 * Config: `{ kicker?, title?, left: {label,title,points[]}, right: {...}, center=true }`
 */
export function createContrastSlide(config = {}) {
    const slide = createSlideShell('contrast', { center: true });

    const header = el('div', { className: 'contrast-header', children: [
        createKicker(config.kicker),
        createHeading(config.title)
    ].filter(Boolean) });

    const grid = el('div', { className: 'contrast-grid', children: [
        buildPanel('left', config.left),
        buildPanel('right', config.right)
    ].filter(Boolean) });

    slide.appendChild(container([header, grid]));
    return slide;
}

function buildPanel(side, spec = {}) {
    const panel = el('div', { className: 'contrast-panel', dataset: { side } });
    const children = [];
    if (spec.label) children.push(el('p', { className: 'kicker', text: String(spec.label) }));
    if (spec.title) children.push(el('h3', { className: 'panel-title', text: String(spec.title) }));
    if (Array.isArray(spec.points)) {
        const ul = el('ul', { className: 'panel-points' });
        for (const point of spec.points) {
            ul.appendChild(el('li', { text: String(point) }));
        }
        children.push(ul);
    }
    for (const child of children.filter(Boolean)) panel.appendChild(child);
    return panel;
}

