import { el, createSlideShell, createKicker, createHeading, container } from './_shared.js';
import { createBuildElement } from '../engine/build.js';

/**
 * chat — message exchange. Each message is wrapped in a Build element so each
 * click reveals one message. Use only for products with a genuine chat/AI
 * interface.
 *
 * Config: `{ kicker?, title?, name?, messages: [{from:'user'|'ai', text}] }`
 *
 * The deck wires up build registration once the slide is attached. Here we
 * pre-stamp each message with data-build-step; deck's mountBuilds() will
 * call service.registerMax on each.
 */
export function createChatSlide(config = {}) {
    const slide = createSlideShell('chat', { center: false });
    if (config.name) slide.dataset.botName = String(config.name);

    const header = el('div', { className: 'chat-header', children: [
        createKicker(config.kicker),
        createHeading(config.title)
    ].filter(Boolean) });

    const thread = el('div', { className: 'chat-thread' });
    const messages = Array.isArray(config.messages) ? config.messages : [];
    messages.forEach((msg, i) => {
        const step = i + 1;
        const bubble = el('div', {
            className: 'chat-bubble',
            dataset: { from: String(msg.from || 'user') }
        });
        if (msg.text) bubble.appendChild(el('p', { className: 'chat-text', text: String(msg.text) }));
        // Wrap each message in a Build element so the deck can reveal on click.
        const build = createBuildElement({ at: step, children: [bubble] });
        thread.appendChild(build);
    });

    slide.appendChild(container([header, thread]));
    return slide;
}

import { el, createSlideShell, createKicker, createHeading, container } from './_shared.js';

/**
 * pricing — tier cards. `highlight: true` on a tier gets an accent badge.
 *
 * Config: `{ kicker?, title?, tiers: [{name, price, period?, blurb?, features[], highlight?}] }`
 */
export function createPricingSlide(config = {}) {
    const slide = createSlideShell('pricing', { center: true });

    const header = el('div', { className: 'pricing-header', children: [
        createKicker(config.kicker),
        createHeading(config.title)
    ].filter(Boolean) });

    const grid = el('div', { className: 'pricing-grid' });
    const tiers = Array.isArray(config.tiers) ? config.tiers : [];
    tiers.forEach((tier) => grid.appendChild(buildTier(tier)));

    slide.appendChild(container([header, grid]));
    return slide;
}

function buildTier(tier = {}) {
    const card = el('div', { className: 'pricing-tier' });
    if (tier.highlight) card.dataset.highlight = 'true';

    const children = [];
    if (tier.name) children.push(el('p', { className: 'tier-name', text: String(tier.name) }));
    if (tier.price) {
        const price = el('p', { className: 'tier-price', text: String(tier.price) });
        if (tier.period) price.dataset.period = String(tier.period);
        children.push(price);
    }
    if (tier.blurb) children.push(el('p', { className: 'tier-blurb', text: String(tier.blurb) }));
    if (Array.isArray(tier.features)) {
        const ul = el('ul', { className: 'tier-features' });
        for (const f of tier.features) ul.appendChild(el('li', { text: String(f) }));
        children.push(ul);
    }
    for (const child of children.filter(Boolean)) card.appendChild(child);
    return card;
}

import { el, createSlideShell, createKicker, createHeading, container } from './_shared.js';

/**
 * accordion — expand/collapse panels using native <details> for accessibility.
 * Used for FAQs and feature detail. Don't use for primary content — audience
 * can't click along during a presented deck.
 *
 * Config: `{ kicker?, title?, items: [{title, body}] }`
 */
export function createAccordionSlide(config = {}) {
    const slide = createSlideShell('accordion', { center: true });

    const header = el('div', { className: 'accordion-header', children: [
        createKicker(config.kicker),
        createHeading(config.title)
    ].filter(Boolean) });

    const list = el('div', { className: 'accordion-list' });
    const items = Array.isArray(config.items) ? config.items : [];
    items.forEach((item) => {
        const details = el('details', { className: 'accordion-item' });
        details.appendChild(el('summary', { className: 'accordion-summary', text: String(item.title || '') }));
        if (item.body) details.appendChild(el('p', { className: 'accordion-body', text: String(item.body) }));
        list.appendChild(details);
    });

    slide.appendChild(container([header, list]));
    return slide;
}

import { el, createSlideShell, createKicker, createHeading, container } from './_shared.js';

/**
 * tabs — 3–5 parallel perspectives on one topic. Sliding pill indicator
 * handled by CSS (data-active attr on the tab bar). Active tab toggled by
 * service.setActiveTab or directly via data-active on click (we wire it up in
 * deck.js if a tabs slide is present).
 *
 * Config: `{ kicker?, title?, tabs: [{label, body?, chart?}] }`
 */
export function createTabsSlide(config = {}) {
    const slide = createSlideShell('tabs', { center: true });

    const header = el('div', { className: 'tabs-header', children: [
        createKicker(config.kicker),
        createHeading(config.title)
    ].filter(Boolean) });

    const bar = el('div', { className: 'tabs-bar', attrs: { role: 'tablist' } });
    const panels = el('div', { className: 'tabs-panels' });
    const tabs = Array.isArray(config.tabs) ? config.tabs : [];
    tabs.forEach((tab, i) => {
        const btn = el('button', {
            className: 'tab-button',
            text: String(tab.label || ''),
            attrs: { role: 'tab', 'aria-selected': i === 0 ? 'true' : 'false' },
            dataset: { tab: String(i) }
        });
        if (i === 0) btn.dataset.active = 'true';
        bar.appendChild(btn);

        const panel = el('div', {
            className: 'tab-panel',
            attrs: { role: 'tabpanel' },
            dataset: { tab: String(i) }
        });
        if (i !== 0) panel.dataset.hidden = 'true';
        if (tab.body) panel.appendChild(el('p', { className: 'tab-body', text: String(tab.body) }));
