import { el, createSlideShell, createKicker, createHeading, container } from './_shared.js';

/**
 * agenda — numbered table-of-contents. Items can be strings or objects with
 * `{title, hint}` for time estimates.
 *
 * Config: `{ kicker?, title?, items: (string|{title,hint})[] }`
 */
export function createAgendaSlide(config = {}) {
    const slide = createSlideShell('agenda', { center: true });

    const header = el('div', { className: 'agenda-header', children: [
        createKicker(config.kicker),
        createHeading(config.title)
    ].filter(Boolean) });

    const list = el('ol', { className: 'agenda-list' });
    const items = Array.isArray(config.items) ? config.items : [];
    items.forEach((item) => {
        const li = el('li', { className: 'agenda-item' });
        const title = typeof item === 'string' ? item : (item?.title || '');
        li.appendChild(el('span', { className: 'agenda-title', text: String(title) }));
        if (item && typeof item === 'object' && item.hint) {
            li.appendChild(el('span', { className: 'agenda-hint', text: String(item.hint) }));
        }
        list.appendChild(li);
    });

    slide.appendChild(container([header, list]));
    return slide;
}

import { el, createSlideShell, container } from './_shared.js';

/**
 * section — chapter divider with ghost number. Used in long decks (~12+ slides)
 * to mark transitions between parts.
 *
 * Config: `{ n (chapter number), kicker?, title? }`
 */
export function createSectionSlide(config = {}) {
    const slide = createSlideShell('section', { center: true });
    if (Number.isFinite(config.n)) slide.dataset.chapter = String(config.n);

    const ghost = el('div', { className: 'section-ghost', text: formatChapter(config.n) });
    const inner = el('div', { className: 'section-inner', children: [
        config.kicker ? el('p', { className: 'kicker', text: String(config.kicker) }) : null,
        config.title ? el('h1', { className: 'display', text: String(config.title) }) : null
    ].filter(Boolean) });

    slide.appendChild(container([ghost, inner]));
    return slide;
}

function formatChapter(n) {
    if (!Number.isFinite(n)) return '';
    // Roman numerals for chapters 1–20, then plain number
    const romans = ['I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII','XIII','XIV','XV','XVI','XVII','XVIII','XIX','XX'];
    return n >= 1 && n <= 20 ? romans[n - 1] : String(n);
}

import { el, createSlideShell, container } from './_shared.js';

/**
 * marquee — logo strip / trust marks. Pure CSS animation (the keyframes live
 * in slides.css). Each item is a plain text label (no images, no markup).
 *
 * Config: `{ items: string[] }`
 */
export function createMarqueeSlide(config = {}) {
    const slide = createSlideShell('marquee', { center: true });

    const track = el('div', { className: 'marquee-track' });
    const items = Array.isArray(config.items) ? config.items : [];
    // Duplicate items so the CSS animation can loop seamlessly
    const sequence = items.length > 0 ? items.concat(items) : [];
    for (const item of sequence) {
        track.appendChild(el('span', { className: 'marquee-item', text: String(item) }));
    }

    slide.appendChild(container([track]));
    return slide;
}

import { el, createSlideShell, createKicker, createHeading, createBody, container, formatFigure } from './_shared.js';

/**
 * globe — canvas 3D globe with markers + arcs. Used ONLY for genuinely
 * geographic stories (per §12.7).
 *
 * Canvas renderer is a Phase 5+ concern — the full bolt-slides GlobeCanvas
 * port is non-trivial and depends on a per-frame rAF loop. v1 ships the DOM
 * shell with markers as a styled list, plus a `[data-globe]` slot the canvas
 * will mount into when fully ported. Stats render as a small grid alongside.
 *
 * Config: `{ kicker?, title?, body?, markers: [{location:[lat,lng],label?,value?,size?}], arcs:[{from,to}], stats:[{value,label}] }`
 */
export function createGlobeSlide(config = {}) {
    const slide = createSlideShell('globe', { center: false });

    const header = el('div', { className: 'globe-header', children: [
        createKicker(config.kicker),
        createHeading(config.title),
        createBody(config.body)
    ].filter(Boolean) });

    const stage = el('div', { className: 'globe-stage' });
    // Canvas slot — the renderer mounts here when ported. For v1, we render
    // a styled placeholder so the slide is not empty.
    const canvasSlot = el('div', { className: 'globe-canvas', dataset: { globe: 'pending' } });
    stage.appendChild(canvasSlot);

    // Markers list — visible proof of real locations even without canvas
    const markers = Array.isArray(config.markers) ? config.markers : [];
    if (markers.length > 0) {
        const list = el('ul', { className: 'globe-markers' });
        for (const marker of markers) {
            const li = el('li', { className: 'globe-marker' });
            if (marker.label) li.appendChild(el('span', { className: 'globe-marker-label', text: String(marker.label) }));
            if (marker.value) li.appendChild(el('span', { className: 'globe-marker-value', text: String(marker.value) }));
            list.appendChild(li);
        }
        stage.appendChild(list);
    }

    // Stats grid alongside
    const stats = Array.isArray(config.stats) ? config.stats : [];
    const statsEl = stats.length > 0
        ? el('div', { className: 'globe-stats', children: stats.map((s) => el('div', {
            className: 'globe-stat',
            children: [
                s.value ? el('p', { className: 'globe-stat-value', text: String(s.value) }) : null,
                s.label ? el('p', { className: 'globe-stat-label', text: String(s.label) }) : null
            ].filter(Boolean)
        })) })
        : null;

    const children = [header, stage];
    if (statsEl) children.push(statsEl);
    slide.appendChild(container(children));
    return slide;
}

