/**
 * dock.js — floating toolbar (Type II).
 *
 * Subscribes to: SLIDE_CHANGED, UI_STATE_CHANGED
 * Publishes: INTENT_SLIDE_NEXT, INTENT_SLIDE_PREV, INTENT_SLIDE_TOGGLE_RAIL,
 *            INTENT_SLIDE_TOGGLE_GRID, INTENT_SLIDE_TOGGLE_FS,
 *            INTENT_SLIDE_TOGGLE_DRAWING, INTENT_SLIDE_HIDE_UI,
 *            INTENT_SLIDE_OPEN_PRESENTER
 *
 * Hides when uiHidden=true. Two rows on desktop (nav + tools), stacked on mobile.
 */

import { el } from '../layouts/_shared.js';

export function initDock(container, eventBus, service) {
    if (!container || !eventBus) return () => {};
    const doc = container.ownerDocument || (typeof document !== 'undefined' ? document : null);
    if (!doc) return () => {};

    const dock = el('div', { className: 'noir-dock', attrs: { role: 'toolbar', 'aria-label': 'Slide controls' } });

    const counter = el('span', { className: 'dock-counter', text: formatCounter(service.index, service.slides.length) });

    const publish = (name) => () => eventBus.publish(name, { timestamp: Date.now() });

    dock.appendChild(el('button', {
        className: 'dock-btn',
        text: '←',
        attrs: { 'aria-label': 'Previous slide' },
        dataset: { intent: 'INTENT_SLIDE_PREV' }
    }));
    dock.appendChild(counter);
    dock.appendChild(el('button', {
        className: 'dock-btn',
        text: '→',
        attrs: { 'aria-label': 'Next slide' },
        dataset: { intent: 'INTENT_SLIDE_NEXT' }
    }));

    const tools = el('div', { className: 'dock-tools' });
    const toolDefs = [
        { label: 'Toggle sidebar', symbol: '☰', intent: 'INTENT_SLIDE_TOGGLE_RAIL' },
        { label: 'Toggle grid',    symbol: '▦', intent: 'INTENT_SLIDE_TOGGLE_GRID' },
        { label: 'Toggle drawing', symbol: '✎', intent: 'INTENT_SLIDE_TOGGLE_DRAWING' },
        { label: 'Fullscreen',     symbol: '⛶', intent: 'INTENT_SLIDE_TOGGLE_FS' },
        { label: 'Presenter',      symbol: '', intent: 'INTENT_SLIDE_OPEN_PRESENTER' },
        { label: 'Hide UI',        symbol: '◉', intent: 'INTENT_SLIDE_HIDE_UI' }
    ];
    for (const t of toolDefs) {
        tools.appendChild(el('button', {
            className: 'dock-btn',
            text: t.symbol,
            attrs: { 'aria-label': t.label, 'title': t.label },
            dataset: { intent: t.intent }
        }));
    }
    dock.appendChild(tools);
    container.appendChild(dock);

    // Click delegation — read intent from data-attr, publish
    const onClick = (e) => {
        const btn = e.target.closest('button[data-intent]');
        if (!btn) return;
        const intent = btn.dataset.intent;
        if (intent) publish(intent)();
    };
    dock.addEventListener('click', onClick);

    const subs = [];
    if (eventBus.subscribe) {
        subs.push(eventBus.subscribe('SLIDE_CHANGED', (payload) => {
            counter.textContent = formatCounter(payload?.slide, payload?.total);
        }));
        subs.push(eventBus.subscribe('UI_STATE_CHANGED', (payload) => {
            dock.dataset.uiHidden = payload?.uiHidden ? 'true' : 'false';
            dock.dataset.drawing  = payload?.drawing  ? 'true' : 'false';
            dock.dataset.railOpen = payload?.railOpen ? 'true' : 'false';
            dock.dataset.gridOpen = payload?.gridOpen ? 'true' : 'false';
        }));
    }

    return () => {
        subs.forEach((fn) => fn && fn());
        dock.removeEventListener('click', onClick);
        if (dock.parentNode) dock.parentNode.removeChild(dock);
    };
}

function formatCounter(slide, total) {
    const s = Number.isFinite(slide) ? slide + 1 : 1;
    const t = Number.isFinite(total) ? total : 0;
    return s + ' / ' + t;
}

/**
 * rail.js — thumbnail sidebar (Type II).
 *
 * Subscribes to: SLIDE_CHANGED, UI_STATE_CHANGED, DECK_READY
 * Publishes: INTENT_SLIDE_GO
 *
 * Renders a vertical list of thumbnail labels (canvas thumbnails are a Phase 5+
 * optimization; v1 uses labeled placeholders that share styling with the grid
 * chrome). Visible only when railOpen=true.
 */

import { el } from '../layouts/_shared.js';

export function initRail(container, eventBus, service) {
    if (!container || !eventBus) return () => {};
    const doc = container.ownerDocument || (typeof document !== 'undefined' ? document : null);
    if (!doc) return () => {};

    const rail = el('aside', {
        className: 'slide-rail',
        attrs: { 'aria-label': 'Slide thumbnails' }
    });
    rail.dataset.open = 'false';
    container.appendChild(rail);

    const list = el('ol', { className: 'rail-list' });
    rail.appendChild(list);

    const renderItems = () => {
        while (list.firstChild) list.removeChild(list.firstChild);
        const slides = Array.isArray(service.slides) ? service.slides : [];
        slides.forEach((slide, i) => {
            const li = el('li', {
                className: 'rail-item',
                dataset: { index: String(i), active: i === service.index ? 'true' : 'false' }
            });
            const label = slide?.type ? slide.type : ('slide ' + (i + 1));
            li.appendChild(el('span', { className: 'rail-thumb', text: String(label) }));
            li.appendChild(el('span', { className: 'rail-num', text: String(i + 1) }));
            list.appendChild(li);
        });
    };

    renderItems();

    const onClick = (e) => {
        const item = e.target.closest('[data-index]');
        if (!item) return;
        const idx = Number(item.dataset.index);
        if (Number.isFinite(idx)) {
            eventBus.publish('INTENT_SLIDE_GO', { index: idx, timestamp: Date.now() });
        }
    };
    list.addEventListener('click', onClick);

    const subs = [];
    if (eventBus.subscribe) {
        subs.push(eventBus.subscribe('DECK_READY', renderItems));
        subs.push(eventBus.subscribe('SLIDE_CHANGED', (payload) => {
            const items = list.querySelectorAll('[data-index]');
            items.forEach((item) => {
                item.dataset.active = Number(item.dataset.index) === payload?.slide ? 'true' : 'false';
            });
        }));
        subs.push(eventBus.subscribe('UI_STATE_CHANGED', (payload) => {
            rail.dataset.open = payload?.railOpen ? 'true' : 'false';
        }));
    }

    return () => {
        subs.forEach((fn) => fn && fn());
        list.removeEventListener('click', onClick);
        if (rail.parentNode) rail.parentNode.removeChild(rail);
    };
}

/**
 * grid.js — grid overview (Type II).
 *
 * Subscribes to: SLIDE_CHANGED, UI_STATE_CHANGED, DECK_READY
 * Publishes: INTENT_SLIDE_GO
 *
 * Full-screen grid of slide labels. Visible only when gridOpen=true. Press
 * Escape or click outside to close.
 */

import { el } from '../layouts/_shared.js';

export function initGrid(container, eventBus, service) {
    if (!container || !eventBus) return () => {};
    const doc = container.ownerDocument || (typeof document !== 'undefined' ? document : null);
    if (!doc) return () => {};

    const grid = el('div', {
        className: 'slide-grid',
        attrs: { 'aria-label': 'Slide overview' }
    });
    grid.dataset.open = 'false';
    container.appendChild(grid);

    const inner = el('div', { className: 'grid-inner' });
    grid.appendChild(inner);

    const renderItems = () => {
        while (inner.firstChild) inner.removeChild(inner.firstChild);
        const slides = Array.isArray(service.slides) ? service.slides : [];
        slides.forEach((slide, i) => {
            const card = el('button', {
                className: 'grid-card',
                dataset: { index: String(i), active: i === service.index ? 'true' : 'false' }
            });
            const label = slide?.type ? slide.type : ('slide ' + (i + 1));
            card.appendChild(el('span', { className: 'grid-thumb', text: String(label) }));
            card.appendChild(el('span', { className: 'grid-num', text: String(i + 1) }));
            inner.appendChild(card);
        });
    };

    renderItems();

    const onClick = (e) => {
        const card = e.target.closest('[data-index]');
        if (card) {
            const idx = Number(card.dataset.index);
            if (Number.isFinite(idx)) {
                eventBus.publish('INTENT_SLIDE_GO', { index: idx, timestamp: Date.now() });
            }
        } else if (e.target === grid) {
            // Click on backdrop closes
            eventBus.publish('INTENT_SLIDE_ESCAPE', { timestamp: Date.now() });
        }
    };
    grid.addEventListener('click', onClick);

    const subs = [];
    if (eventBus.subscribe) {
        subs.push(eventBus.subscribe('DECK_READY', renderItems));
        subs.push(eventBus.subscribe('SLIDE_CHANGED', (payload) => {
            const items = inner.querySelectorAll('[data-index]');
            items.forEach((item) => {
                item.dataset.active = Number(item.dataset.index) === payload?.slide ? 'true' : 'false';
            });
        }));
        subs.push(eventBus.subscribe('UI_STATE_CHANGED', (payload) => {
            grid.dataset.open = payload?.gridOpen ? 'true' : 'false';
        }));
    }

    return () => {
        subs.forEach((fn) => fn && fn());
        grid.removeEventListener('click', onClick);
        if (grid.parentNode) grid.parentNode.removeChild(grid);
    };
}

/**
 * presenter.js — presenter overlay (Type II).
 *
 * Only mounted when ?presenter=1 is in the URL (set on the SlideDeckService).
 * Subscribes to PRESENTER_SYNC (cross-tab from main deck) and SLIDE_CHANGED.
 * Publishes INTENT_SLIDE_NOTE_UPDATE.
 *
 * Layout: current slide preview + next slide preview + notes textarea + timer.
 * Notes persist to localStorage (device-scoped, same as bolt-slides).
 */

import { el } from '../layouts/_shared.js';

const TIMER_KEY = 'csma-slides-timer-start';

export function initPresenter(container, eventBus, service) {
    if (!container || !eventBus) return () => {};
    const doc = container.ownerDocument || (typeof document !== 'undefined' ? document : null);
    const win = doc?.defaultView || (typeof window !== 'undefined' ? window : null);
    if (!doc || !win) return () => {};

    const overlay = el('div', { className: 'presenter-overlay' });
    container.appendChild(overlay);

    // Current slide preview
    const current = el('section', { className: 'presenter-current' });
    current.appendChild(el('p', { className: 'kicker', text: 'Current' }));
    const currentLabel = el('p', { className: 'presenter-slide-label', text: labelFor(service) });
    current.appendChild(currentLabel);

    // Next slide preview
    const next = el('section', { className: 'presenter-next' });
    next.appendChild(el('p', { className: 'kicker', text: 'Next' }));
    const nextLabel = el('p', { className: 'presenter-slide-label', text: labelFor(service, service.index + 1) });
    next.appendChild(nextLabel);

    // Notes textarea
    const notesWrap = el('section', { className: 'presenter-notes' });
    notesWrap.appendChild(el('label', {
        className: 'presenter-notes-label',
        text: 'Notes',
        attrs: { for: 'csma-presenter-notes' }
    }));
    const textarea = el('textarea', {
        className: 'presenter-notes-input',
        attrs: { id: 'csma-presenter-notes', maxlength: '5000', placeholder: 'Add talking points for this slide…' }
    });
    textarea.value = service.getNote(service.index) || '';
    notesWrap.appendChild(textarea);

    // Timer
    const timerWrap = el('section', { className: 'presenter-timer' });
    const timerDisplay = el('p', { className: 'presenter-timer-display', text: '00:00' });
    timerWrap.appendChild(timerDisplay);

    overlay.appendChild(current);
    overlay.appendChild(next);
    overlay.appendChild(notesWrap);
    overlay.appendChild(timerWrap);

    // Timer — persist start across reloads (device-scoped)
    let timerStart = null;
    try {
        const stored = win.localStorage?.getItem(TIMER_KEY);
        timerStart = stored ? Number(stored) : null;
    } catch { /* noop */ }
    if (!Number.isFinite(timerStart)) {
        timerStart = Date.now();
        try { win.localStorage?.setItem(TIMER_KEY, String(timerStart)); } catch { /* noop */ }
    }
    const tickTimer = () => {
        const elapsed = Math.max(0, Math.floor((Date.now() - timerStart) / 1000));
        const mm = String(Math.floor(elapsed / 60)).padStart(2, '0');
        const ss = String(elapsed % 60).padStart(2, '0');
        timerDisplay.textContent = mm + ':' + ss;
    };
    const intervalId = win.setInterval(tickTimer, 1000);
    tickTimer();

    // Note editing
    let saveTimeout = null;
    const onNotesInput = () => {
        if (saveTimeout) win.clearTimeout(saveTimeout);
        const text = textarea.value;
        saveTimeout = win.setTimeout(() => {
            eventBus.publish('INTENT_SLIDE_NOTE_UPDATE', {
                slide: service.index,
                text,
                timestamp: Date.now()
            });
            saveTimeout = null;
        }, 400);
    };
    textarea.addEventListener('input', onNotesInput);

    const subs = [];
    const sync = (slide, clicks) => {
        currentLabel.textContent = labelFor(service, slide);
        nextLabel.textContent = labelFor(service, (slide ?? service.index) + 1);
        textarea.value = service.getNote(slide) || '';
    };

    if (eventBus.subscribe) {
        subs.push(eventBus.subscribe('PRESENTER_SYNC', (payload) => {
            sync(payload?.slide, payload?.clicks);
        }));
        subs.push(eventBus.subscribe('SLIDE_CHANGED', (payload) => {
            sync(payload?.slide, payload?.clicks);
        }));
    }

    return () => {
        if (saveTimeout) win.clearTimeout(saveTimeout);
        win.clearInterval(intervalId);
        textarea.removeEventListener('input', onNotesInput);
        subs.forEach((fn) => fn && fn());
        if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
    };
}

function labelFor(service, idx) {
    const i = Number.isFinite(idx) ? idx : service.index;
    if (i < 0 || i >= service.slides.length) return '(end)';
    const slide = service.slides[i];
    return slide?.title || slide?.type || ('slide ' + (i + 1));
}

