  font-weight: var(--font-weight-bold);
  font-variant-numeric: tabular-nums;
}

/* Mobile: stack presenter panels */
@media (max-width: 768px) {
  .presenter-overlay {
    grid-template-columns: 1fr;
    grid-template-areas:
      "timer"
      "current"
      "next"
