                expect(el, `${name} returned null`).not.toBeNull();
                expect(el.tagName).toBe('DIV');
                expect(el.classList.contains('slide')).toBe(true);
                expect(el.dataset.layout, `${name} must set data-layout`).toBe(name);
            });
        }
    });

