import { describe, it, expect, beforeEach } from 'vitest';
import { EventBus } from '../../src/runtime/EventBus.js';
import { SlideDeckService } from '../../src/modules/slides/services/SlideDeckService.js';
import { SlidesContracts } from '../../src/modules/slides/contracts/slides-contracts.js';
import { createBuildElement, bindBuildToService, syncBuildVisibility } from '../../src/modules/slides/engine/build.js';

/**
 * Build (click-reveal) state machine — verify the element's data-visible
 * toggles correctly as the service click count advances.
 */

describe('Build (click-reveal) elements', () => {
    let eventBus;
    let service;

    beforeEach(() => {
        eventBus = new EventBus();
        eventBus.contracts = SlidesContracts;
        service = new SlideDeckService(eventBus);
        service.init({ slides: [{ type: 'cover' }, { type: 'cta' }] });
        service.index = 0;
        service.clicks = 0;
    });

    it('createBuildElement stamps step + initial visibility', () => {
        const visible = createBuildElement({ at: 1, currentClicks: 1 });
        expect(visible.dataset.buildStep).toBe('1');
        expect(visible.dataset.visible).toBe('true');

        const hidden = createBuildElement({ at: 2, currentClicks: 0 });
        expect(hidden.dataset.buildStep).toBe('2');
        expect(hidden.dataset.visible).toBe('false');
    });

    it('clamps at to minimum 1', () => {
        const b = createBuildElement({ at: 0 });
        expect(b.dataset.buildStep).toBe('1');
    });

    it('appends children', () => {
        const child = document.createElement('p');
        child.textContent = 'hello';
        const b = createBuildElement({ at: 1, children: [child] });
        expect(b.children.length).toBe(1);
        expect(b.children[0].tagName).toBe('P');
    });

    it('registers max with the service', () => {
        createBuildElement({ at: 3, service, slideIndex: 1 });
        expect(service.maxClicks.get(1)).toBe(3);
    });

    it('bindBuildToService toggles visibility on BUILD_ADVANCED', () => {
        const build = createBuildElement({ at: 2, currentClicks: 0 });
        const unbind = bindBuildToService(build, eventBus, 0);
        expect(build.dataset.visible).toBe('false');

        // First click — not yet visible (step=2, click=1)
        eventBus.publish('BUILD_ADVANCED', { slide: 0, click: 1, maxClicks: 2 });
        expect(build.dataset.visible).toBe('false');

        // Second click — now visible
        eventBus.publish('BUILD_ADVANCED', { slide: 0, click: 2, maxClicks: 2 });
        expect(build.dataset.visible).toBe('true');

        unbind();
        // After unbind, no more updates
        eventBus.publish('BUILD_ADVANCED', { slide: 0, click: 1, maxClicks: 2 });
        expect(build.dataset.visible).toBe('true');
    });

    it('bindBuildToService ignores events for other slides', () => {
        const build = createBuildElement({ at: 1, currentClicks: 0 });
        bindBuildToService(build, eventBus, 5);
        eventBus.publish('BUILD_ADVANCED', { slide: 0, click: 5, maxClicks: 5 });
        expect(build.dataset.visible).toBe('false');
    });

    it('syncBuildVisibility forces a re-render from raw clicks', () => {
        const build = createBuildElement({ at: 3, currentClicks: 0 });
        expect(build.dataset.visible).toBe('false');
        syncBuildVisibility(build, 3);
        expect(build.dataset.visible).toBe('true');
        syncBuildVisibility(build, 2);
        expect(build.dataset.visible).toBe('false');
    });

    it('service.next() walks through build steps then advances slide', () => {
        // slide 0: 2 build steps
        service.registerMax(2, 0);
        // First click: build step 1
        service.next();
        expect(service.clicks).toBe(1);
        expect(service.index).toBe(0);
        // Second click: build step 2
        service.next();
        expect(service.clicks).toBe(2);
        expect(service.index).toBe(0);
        // Third click: advance to slide 1
        service.next();
        expect(service.index).toBe(1);
        expect(service.clicks).toBe(0);
    });
});

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { EventBus } from '../../src/runtime/EventBus.js';
import { SlideDeckService } from '../../src/modules/slides/services/SlideDeckService.js';
import { SlidesContracts } from '../../src/modules/slides/contracts/slides-contracts.js';

/**
 * Cross-tab sync — verify the main deck broadcasts state and the presenter
 * tab follows via PRESENTER_SYNC.
 *
 * We mock BroadcastChannel with a simple shared bus so two services in the
 * same process can talk to each other (jsdom doesn't ship a real impl).
 */

class MockBroadcastChannel {
    constructor(name) {
        this.name = name;
        this.listeners = new Set();
        MockBroadcastChannel.BY_NAME.get(name)?.forEach((ch) => ch._peerRemoved);
        if (!MockBroadcastChannel.BY_NAME.has(name)) {
            MockBroadcastChannel.BY_NAME.set(name, new Set());
        }
        MockBroadcastChannel.BY_NAME.get(name).add(this);
    }
    addEventListener(_type, fn) { this.listeners.add(fn); }
    removeEventListener(_type, fn) { this.listeners.delete(fn); }
    postMessage(msg) {
        for (const peer of MockBroadcastChannel.BY_NAME.get(this.name) || []) {
            if (peer === this) continue;
            for (const fn of peer.listeners) {
                // Async tick to mimic real BroadcastChannel dispatch
                setTimeout(() => fn({ data: msg }), 0);
            }
        }
    }
    close() {
        MockBroadcastChannel.BY_NAME.get(this.name)?.delete(this);
    }
}
MockBroadcastChannel.BY_NAME = new Map();

describe('Cross-tab presenter sync', () => {
    let originalBC;
    let originalLocalStore;

    beforeEach(() => {
        originalBC = globalThis.BroadcastChannel;
        globalThis.BroadcastChannel = MockBroadcastChannel;
        MockBroadcastChannel.BY_NAME.clear();
    });

    afterEach(() => {
        globalThis.BroadcastChannel = originalBC;
        vi.restoreAllMocks();
    });

    it('main deck broadcasts state on slide advance; presenter follows', async () => {
        const slides = [{ type: 'cover' }, { type: 'cta' }, { type: 'section', n: 1 }];

        // Main deck
        const mainBus = new EventBus();
        mainBus.contracts = SlidesContracts;
        const main = new SlideDeckService(mainBus);
        main.init({ slides });
        expect(main.isPresenter).toBe(false);

        // Presenter tab — simulate ?presenter=1
        const originalSearch = window.location.search;
        Object.defineProperty(window, 'location', {
            value: { ...window.location, search: '?presenter=1', href: 'http://localhost/?presenter=1' },
            writable: true,
            configurable: true
        });

        const presenterBus = new EventBus();
        presenterBus.contracts = SlidesContracts;
        const presenter = new SlideDeckService(presenterBus);
        presenter.init({ slides });

        expect(presenter.isPresenter).toBe(true);

        let captured = null;
        presenterBus.subscribe('PRESENTER_SYNC', (p) => { captured = p; });

        // Main advances → presenter should receive sync
        main.next();
        await new Promise((r) => setTimeout(r, 10));

        expect(captured).not.toBeNull();
        expect(presenter.index).toBe(main.index);
        expect(presenter.clicks).toBe(main.clicks);

        // Restore location
        Object.defineProperty(window, 'location', {
            value: { ...window.location, search: originalSearch, href: 'http://localhost/' },
            writable: true,
            configurable: true
        });

        main.destroy();
        presenter.destroy();
    });

    it('presenter does NOT broadcast back to main (one-way)', async () => {
        const slides = [{ type: 'cover' }, { type: 'cta' }];

        const mainBus = new EventBus();
        mainBus.contracts = SlidesContracts;
        const main = new SlideDeckService(mainBus);
        main.init({ slides });

        Object.defineProperty(window, 'location', {
            value: { ...window.location, search: '?presenter=1', href: 'http://localhost/?presenter=1' },
            writable: true,
            configurable: true
        });
        const presenterBus = new EventBus();
        presenterBus.contracts = SlidesContracts;
        const presenter = new SlideDeckService(presenterBus);
        presenter.init({ slides });

        let mainChanged = false;
        mainBus.subscribe('SLIDE_CHANGED', () => { mainChanged = true; });

        // Presenter advances — main should not move
        const mainIndexBefore = main.index;
        presenter.next();
        await new Promise((r) => setTimeout(r, 10));
        expect(main.index).toBe(mainIndexBefore);
        expect(mainChanged).toBe(false);

        Object.defineProperty(window, 'location', {
            value: { ...window.location, search: '', href: 'http://localhost/' },
            writable: true,
            configurable: true
        });
        main.destroy();
        presenter.destroy();
    });

    it('gracefully degrades when BroadcastChannel is unavailable', () => {
        globalThis.BroadcastChannel = undefined;
        const bus = new EventBus();
        bus.contracts = SlidesContracts;
        const svc = new SlideDeckService(bus);
        expect(() => svc.init({ slides: [{ type: 'cover' }] })).not.toThrow();
        // Sync channel never created
        expect(svc.syncChannel).toBeNull();
        // next() still works (just doesn't broadcast)
        svc.next();
        expect(svc.index).toBe(0); // only 1 slide, can't advance
        svc.destroy();
    });
});

